// OrgAuction OrgAuctionInput with `lots` replaced by OrgLot[] plus server fields.
type OrgAuction struct {
	Approvals []Approval `json:"approvals"`
	Award     *struct {
		At time.Time `json:"at"`
		By string    `json:"by"`

		// Lines Award lines per lot.
		Lines          [][]AllocationLine `json:"lines"`
		PoNumber       *string            `json:"poNumber,omitempty"`
		Reason         string             `json:"reason"`
		TransactionIds *[]string          `json:"transactionIds,omitempty"`
	} `json:"award,omitempty"`
	CategoryId    CategoryId       `json:"categoryId"`
	Code          string           `json:"code"`
	CreatedAt     time.Time        `json:"createdAt"`
	CreatedBy     string           `json:"createdBy"`
	Id            string           `json:"id"`
	Invited       []string         `json:"invited"`
	Lots          []OrgLot         `json:"lots"`
	MultiLot      bool             `json:"multiLot"`
	Objective     AuctionObjective `json:"objective"`
	ProcurementId *string          `json:"procurementId,omitempty"`
	Qualification struct {
		Documents []string `json:"documents"`
		MinRating float64  `json:"minRating"`
		Regions   []string `json:"regions"`
	} `json:"qualification"`
	RequiredApprovers []string `json:"requiredApprovers"`
	Rules             struct {
		AutoExtension bool `json:"autoExtension"`

		// Award TypeScript name `AwardRule` in org.ts (renamed to avoid clashing with the market rules `AwardRule`). lowest = cheapest bidder (highest when selling); weighted = combined score; split = Smart Allocation across suppliers; bundled = all lots to one supplier with the best total.
		Award      OrgAwardRule  `json:"award"`
		MinStepIdr int           `json:"minStepIdr"`
		Visibility BidVisibility `json:"visibility"`

		// Weights Scoring weights; they need not sum to 100 (defaults price 60, quality 20, delivery 10, reliability 10).
		Weights  Weights      `json:"weights"`
		Withdraw WithdrawRule `json:"withdraw"`
	} `json:"rules"`
	Schedule struct {
		DurationMinutes int        `json:"durationMinutes"`
		StartsAt        *time.Time `json:"startsAt,omitempty"`
	} `json:"schedule"`
	Status   OrgAuctionStatus `json:"status"`
	Title    string           `json:"title"`
	Type     AuctionType      `json:"type"`
	ValueIdr int              `json:"valueIdr"`
}

